    exponent = 2 if squared else 1
    unit = xmin.unit
    xmax = u.Quantity(xmax).to(unit)
    b = self.impact_parameter(separation, distance).to(unit)

    with np.errstate(divide="ignore", invalid="ignore"):
        if b.value == 0:
            # Degenerate ray through the halo centre: the Jacobian is unity
            # and the requested radial interval is integrated directly.
            if xmin.value > 0:
                x = self._radial_grid(xmin, xmax, ndecade)
                return trapz_loglog(func(x, separation, squared), x).sum()
            # The halo centre itself is the lower bound. A logarithmic grid
            # is not defined there, so the innermost interval is integrated
            # analytically from the local power law of the integrand, which
            # diverges for a density profile steep enough at the centre.
            x = self._radial_grid(
                xmax * 10.0**-self.N_DECADES_TO_CENTER, xmax, ndecade
            )
            y = func(x, separation, squared)
            return trapz_loglog(y, x).sum() + self._integral_to_center(x, y)

        # Radii below the impact parameter are not reached by the ray.
        tmin, tmax = (
            np.arccosh(np.clip((u.Quantity(_).to_value(unit) / b.value), 1.0, None))
            for _ in (xmin, xmax)
        )
        n = max(2, int((tmax - tmin) / np.log(10) * ndecade))
        t = np.linspace(tmin, tmax, n)
        radius = b * np.cosh(t)
        y = func(radius, separation, squared) * (b * np.sinh(t))
        # At the closest approach the substituted integrand is the finite
        # limit rho(b) ** exponent * b, evaluated here as 0 * inf.
        closest = t == 0
        if np.any(closest):
            y[closest] = self(radius[closest]) ** exponent * radius[closest]
        return self._trapezoid(y, t)

@staticmethod
def _radial_grid(xmin, xmax, ndecade):
    """Logarithmic radial integration grid keeping the requested bounds."""
    unit = xmin.unit
    logmin = np.log10(xmin.value)
    logmax = np.log10(u.Quantity(xmax).to_value(unit))
    n = max(2, int((logmax - logmin) * ndecade))
    return np.logspace(logmin, logmax, n) * unit

@staticmethod
def _integral_to_center(x, y):
    r"""Integral from the halo centre up to the innermost grid point.

    The integrand is extrapolated as a power law, :math:`y \propto x^s`,
    giving :math:`x_0 y_0 / (s + 1)`. This diverges for :math:`s \leq -1`,
    i.e. for a density profile that is too steep at the centre to give a
    finite line-of-sight integral through it.
    """
    index = np.log((y[1] / y[0]).to_value("")) / np.log((x[1] / x[0]).to_value(""))
    if index <= -1:
        return np.inf * y[0] * x[0]
    return y[0] * x[0] / (index + 1)

@staticmethod
def _trapezoid(y, x):
    """Trapezoidal rule for a smooth integrand on a regular grid."""
    return np.sum((y[1:] + y[:-1]) / 2 * np.diff(x))

